/// Split a raw ADTS clip into full per-frame byte slices.
fn split_frames(clip: &[u8]) -> Vec<Vec<u8>> {
    let mut frames = Vec::new();
    let mut pos = 0;
    while pos < clip.len() {
        let hdr = match AdtsHeader::parse(&clip[pos..]) {
            Ok(h) => h,
            Err(_) => break,
        };
        let end = pos + hdr.frame_length;
        if end > clip.len() {
            break;
        }
        frames.push(clip[pos..end].to_vec());
        pos = end;
    }
    frames
}

fn bench_decode(c: &mut Criterion) {
    let frames = split_frames(AAC_CLIP);

    let mut group = c.benchmark_group("aac_decode");
    group.throughput(Throughput::Elements(frames.len() as u64));

    group.bench_function("decode_frames", |b| {
        b.iter(|| {
            let mut dec = AacDecoder::new();
            for f in &frames {
                let pkt = Packet {
                    pts: tpt_kinetix_core::timestamp::Timestamp::NONE,
                    dts: tpt_kinetix_core::timestamp::Timestamp::NONE,
                    data: f.clone(),
                    stream_index: 0,
                    is_key_frame: true,
                };
                let _ = dec.decode(&pkt).expect("decode");
            }
        });
    });

    group.finish();
}

criterion_group!(benches, bench_decode);
criterion_main!(benches);
